'use client';

import React, { memo, useState } from 'react';
import {
    FileText,
    Plus,
    Search,
    Tag,
    Calendar,
    MoreHorizontal,
    Edit3,
    Trash2,
    Star,
    Clock
} from 'lucide-react';
import { Logger } from '../../../../../../shared/logger';

interface Note {
    id: string;
    title: string;
    content: string;
    tags: string[];
    category: 'research' | 'idea' | 'plot' | 'character' | 'dialogue' | 'other';
    priority: 'low' | 'medium' | 'high';
    createdAt: Date;
    updatedAt: Date;
    isPinned: boolean;
}

interface NoteSidebarProps {
    projectId: string;
    notes: Note[];
    onAddNote?: () => void;
    onEditNote?: (id: string) => void;
    onDeleteNote?: (id: string) => void;
    onSelectNote?: (id: string) => void;
    onTogglePin?: (id: string) => void;
    selectedNoteId?: string;
}

// 🔥 메모 관리 전용 사이드바 스타일
const NOTE_SIDEBAR_STYLES = {
    container: 'w-64 bg-gradient-to-b from-orange-50 to-amber-50 dark:from-gray-800 dark:to-gray-900 border-r border-orange-200 dark:border-gray-700 p-4 h-full overflow-y-auto',
    header: 'flex items-center gap-3 mb-6 pb-4 border-b border-orange-200 dark:border-gray-700',
    headerIcon: 'w-6 h-6 text-orange-600 dark:text-orange-400',
    headerTitle: 'text-lg font-semibold text-gray-900 dark:text-gray-100',

    // 검색 및 필터
    actionSection: 'mb-6 space-y-3',
    searchBox: 'w-full px-3 py-2 border border-orange-200 dark:border-gray-600 rounded-lg text-sm bg-white dark:bg-gray-800 placeholder-gray-500',
    filterButtons: 'flex gap-1 flex-wrap',
    filterButton: 'px-2 py-1 text-xs rounded-full border transition-colors',
    filterButtonActive: 'bg-orange-600 text-white border-orange-600',
    filterButtonInactive: 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-400 border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-700',
    addButton: 'w-full flex items-center gap-2 px-3 py-2 bg-orange-600 hover:bg-orange-700 text-white rounded-lg transition-colors text-sm font-medium',
    addButtonIcon: 'w-4 h-4',

    // 메모 카드
    noteList: 'space-y-3',
    noteCard: 'bg-white dark:bg-gray-800 rounded-lg p-3 border border-orange-100 dark:border-gray-700 transition-all hover:shadow-md',
    noteCardSelected: 'bg-orange-100 dark:bg-orange-900/30 border-orange-300 dark:border-orange-600',
    noteCardPinned: 'ring-1 ring-orange-300 dark:ring-orange-600',
    noteHeader: 'flex items-start gap-2 mb-2',
    noteInfo: 'flex-1 min-w-0',
    noteTitle: 'font-medium text-gray-900 dark:text-gray-100 text-sm line-clamp-1',
    noteContent: 'text-xs text-gray-600 dark:text-gray-400 line-clamp-2 mb-2',
    noteMeta: 'flex items-center gap-2 text-xs text-gray-500',
    noteActions: 'flex gap-1',

    // 태그
    tagContainer: 'flex flex-wrap gap-1 mb-2',
    tag: 'inline-flex items-center px-2 py-1 text-xs bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-300 rounded-full',

    // 우선순위 색상
    priorityDot: 'w-2 h-2 rounded-full',
    priorityHigh: 'bg-red-500',
    priorityMedium: 'bg-yellow-500',
    priorityLow: 'bg-green-500',

    // 카테고리 색상
    categoryDot: 'w-3 h-3 rounded-full',

    // 액션 버튼
    actionButton: 'w-5 h-5 p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 rounded',
    pinButton: 'w-5 h-5 p-1 text-orange-400 hover:text-orange-600 dark:hover:text-orange-300 rounded',
    menuButton: 'w-5 h-5 p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 rounded',

    // 빈 상태
    emptyState: 'text-center py-8 text-gray-500 dark:text-gray-400',
    emptyIcon: 'w-12 h-12 mx-auto mb-3 opacity-50',
    emptyText: 'text-sm',
    emptySubtext: 'text-xs mt-1'
} as const;

// 카테고리별 색상
const getCategoryColor = (category: Note['category']) => {
    switch (category) {
        case 'research': return 'bg-blue-500';
        case 'idea': return 'bg-yellow-500';
        case 'plot': return 'bg-purple-500';
        case 'character': return 'bg-pink-500';
        case 'dialogue': return 'bg-green-500';
        case 'other': return 'bg-gray-500';
        default: return 'bg-gray-500';
    }
};

// 카테고리별 한글 이름
const getCategoryName = (category: Note['category']) => {
    switch (category) {
        case 'research': return '자료';
        case 'idea': return '아이디어';
        case 'plot': return '플롯';
        case 'character': return '인물';
        case 'dialogue': return '대화';
        case 'other': return '기타';
        default: return '기타';
    }
};

// 시간 포맷팅
const formatTimeAgo = (date: Date) => {
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return '오늘';
    if (diffDays === 1) return '어제';
    if (diffDays < 7) return `${diffDays}일 전`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)}주 전`;
    return `${Math.floor(diffDays / 30)}개월 전`;
};

export const NoteSidebar = memo(function NoteSidebar({
    projectId,
    notes,
    onAddNote,
    onEditNote,
    onDeleteNote,
    onSelectNote,
    onTogglePin,
    selectedNoteId
}: NoteSidebarProps): React.ReactElement {
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCategory, setSelectedCategory] = useState<Note['category'] | 'all'>('all');
    const [openMenuId, setOpenMenuId] = useState<string | null>(null);

    Logger.debug('NOTE_SIDEBAR', 'Rendering note sidebar', {
        projectId,
        noteCount: notes.length
    });

    // 필터링된 메모
    const filteredNotes = notes
        .filter(note => {
            const matchesSearch = note.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                note.content.toLowerCase().includes(searchTerm.toLowerCase()) ||
                note.tags.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()));
            const matchesCategory = selectedCategory === 'all' || note.category === selectedCategory;
            return matchesSearch && matchesCategory;
        })
        .sort((a, b) => {
            // 고정된 메모가 먼저 오도록
            if (a.isPinned && !b.isPinned) return -1;
            if (!a.isPinned && b.isPinned) return 1;
            // 그 다음은 업데이트 시간 순
            return b.updatedAt.getTime() - a.updatedAt.getTime();
        });

    // 카테고리 필터 버튼
    const categories: Array<{ value: Note['category'] | 'all', label: string }> = [
        { value: 'all', label: '전체' },
        { value: 'idea', label: '아이디어' },
        { value: 'plot', label: '플롯' },
        { value: 'character', label: '인물' },
        { value: 'research', label: '자료' },
        { value: 'dialogue', label: '대화' },
        { value: 'other', label: '기타' }
    ];

    // 메뉴 토글
    const toggleMenu = (noteId: string, event: React.MouseEvent) => {
        event.stopPropagation();
        setOpenMenuId(openMenuId === noteId ? null : noteId);
    };

    return (
        <div className={NOTE_SIDEBAR_STYLES.container}>
            {/* 헤더 */}
            <div className={NOTE_SIDEBAR_STYLES.header}>
                <FileText className={NOTE_SIDEBAR_STYLES.headerIcon} />
                <h3 className={NOTE_SIDEBAR_STYLES.headerTitle}>메모 관리</h3>
            </div>

            {/* 검색, 필터 및 추가 버튼 */}
            <div className={NOTE_SIDEBAR_STYLES.actionSection}>
                <div className="relative">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                        type="text"
                        placeholder="메모 검색..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className={`${NOTE_SIDEBAR_STYLES.searchBox} pl-10`}
                    />
                </div>

                {/* 카테고리 필터 */}
                <div className={NOTE_SIDEBAR_STYLES.filterButtons}>
                    {categories.map(category => (
                        <button
                            key={category.value}
                            onClick={() => setSelectedCategory(category.value)}
                            className={`${NOTE_SIDEBAR_STYLES.filterButton} ${selectedCategory === category.value
                                    ? NOTE_SIDEBAR_STYLES.filterButtonActive
                                    : NOTE_SIDEBAR_STYLES.filterButtonInactive
                                }`}
                        >
                            {category.label}
                        </button>
                    ))}
                </div>

                <button
                    onClick={onAddNote}
                    className={NOTE_SIDEBAR_STYLES.addButton}
                >
                    <Plus className={NOTE_SIDEBAR_STYLES.addButtonIcon} />
                    새 메모 추가
                </button>
            </div>

            {/* 메모 목록 */}
            <div className={NOTE_SIDEBAR_STYLES.noteList}>
                {filteredNotes.length === 0 ? (
                    <div className={NOTE_SIDEBAR_STYLES.emptyState}>
                        <FileText className={NOTE_SIDEBAR_STYLES.emptyIcon} />
                        <p className={NOTE_SIDEBAR_STYLES.emptyText}>
                            {searchTerm || selectedCategory !== 'all' ? '검색 결과가 없습니다' : '아직 메모가 없습니다'}
                        </p>
                        <p className={NOTE_SIDEBAR_STYLES.emptySubtext}>
                            {searchTerm || selectedCategory !== 'all' ? '다른 검색어나 카테고리를 시도해보세요' : '새 메모를 추가해보세요'}
                        </p>
                    </div>
                ) : (
                    filteredNotes.map(note => {
                        const isSelected = selectedNoteId === note.id;

                        return (
                            <div
                                key={note.id}
                                className={`${NOTE_SIDEBAR_STYLES.noteCard} ${isSelected ? NOTE_SIDEBAR_STYLES.noteCardSelected : ''
                                    } ${note.isPinned ? NOTE_SIDEBAR_STYLES.noteCardPinned : ''} group cursor-pointer`}
                                onClick={() => onSelectNote?.(note.id)}
                            >
                                {/* 헤더 */}
                                <div className={NOTE_SIDEBAR_STYLES.noteHeader}>
                                    <div className={NOTE_SIDEBAR_STYLES.noteInfo}>
                                        <div className={NOTE_SIDEBAR_STYLES.noteTitle}>
                                            {note.isPinned && <Star className="inline w-3 h-3 mr-1 text-orange-500" />}
                                            {note.title}
                                        </div>
                                    </div>

                                    <div className={NOTE_SIDEBAR_STYLES.noteActions}>
                                        <button
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                onTogglePin?.(note.id);
                                            }}
                                            className={note.isPinned ? NOTE_SIDEBAR_STYLES.pinButton : NOTE_SIDEBAR_STYLES.actionButton}
                                        >
                                            <Star className={note.isPinned ? 'fill-current' : ''} />
                                        </button>

                                        <button
                                            onClick={(e) => toggleMenu(note.id, e)}
                                            className={`${NOTE_SIDEBAR_STYLES.menuButton} opacity-0 group-hover:opacity-100 transition-opacity`}
                                        >
                                            <MoreHorizontal />
                                        </button>
                                    </div>
                                </div>

                                {/* 내용 미리보기 */}
                                {note.content && (
                                    <div className={NOTE_SIDEBAR_STYLES.noteContent}>
                                        {note.content}
                                    </div>
                                )}

                                {/* 태그 */}
                                {note.tags.length > 0 && (
                                    <div className={NOTE_SIDEBAR_STYLES.tagContainer}>
                                        {note.tags.slice(0, 3).map(tag => (
                                            <span key={tag} className={NOTE_SIDEBAR_STYLES.tag}>
                                                <Tag className="w-2 h-2 mr-1" />
                                                {tag}
                                            </span>
                                        ))}
                                        {note.tags.length > 3 && (
                                            <span className={NOTE_SIDEBAR_STYLES.tag}>
                                                +{note.tags.length - 3}
                                            </span>
                                        )}
                                    </div>
                                )}

                                {/* 메타 정보 */}
                                <div className={NOTE_SIDEBAR_STYLES.noteMeta}>
                                    <div className={`${NOTE_SIDEBAR_STYLES.categoryDot} ${getCategoryColor(note.category)}`} />
                                    <span>{getCategoryName(note.category)}</span>
                                    <div className={`${NOTE_SIDEBAR_STYLES.priorityDot} ${note.priority === 'high' ? NOTE_SIDEBAR_STYLES.priorityHigh :
                                            note.priority === 'medium' ? NOTE_SIDEBAR_STYLES.priorityMedium :
                                                NOTE_SIDEBAR_STYLES.priorityLow
                                        }`} />
                                    <Clock className="w-3 h-3" />
                                    <span>{formatTimeAgo(note.updatedAt)}</span>
                                </div>

                                {/* 드롭다운 메뉴 */}
                                {openMenuId === note.id && (
                                    <div className="absolute right-2 top-8 w-28 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-lg z-10">
                                        <button
                                            className="flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 w-full text-left rounded-t-lg"
                                            onClick={() => {
                                                onEditNote?.(note.id);
                                                setOpenMenuId(null);
                                            }}
                                        >
                                            <Edit3 className="w-4 h-4" />
                                            편집
                                        </button>
                                        <button
                                            className="flex items-center gap-2 px-3 py-2 text-sm text-red-600 hover:bg-gray-100 dark:hover:bg-gray-700 w-full text-left rounded-b-lg"
                                            onClick={() => {
                                                onDeleteNote?.(note.id);
                                                setOpenMenuId(null);
                                            }}
                                        >
                                            <Trash2 className="w-4 h-4" />
                                            삭제
                                        </button>
                                    </div>
                                )}
                            </div>
                        );
                    })
                )}
            </div>
        </div>
    );
});
