'use client';

import React, { memo, useState } from 'react';
import {
    BookOpen,
    FileText,
    FolderOpen,
    Plus,
    MoreVertical,
    Edit3,
    Trash2,
    ChevronRight,
    ChevronDown
} from 'lucide-react';
import { Logger } from '../../../../../../shared/logger';

interface StructureItem {
    id: string;
    title: string;
    type: 'synopsis' | 'chapter' | 'note' | 'folder';
    children?: StructureItem[];
    wordCount?: number;
    isExpanded?: boolean;
}

interface StructureSidebarProps {
    projectId: string;
    structure: StructureItem[];
    onAddItem?: (type: StructureItem['type'], parentId?: string) => void;
    onEditItem?: (id: string) => void;
    onDeleteItem?: (id: string) => void;
    onSelectItem?: (id: string) => void;
    selectedItemId?: string;
}

// 🔥 구조 관리 전용 사이드바 스타일
const STRUCTURE_SIDEBAR_STYLES = {
    container: 'w-64 bg-gradient-to-b from-green-50 to-emerald-50 dark:from-gray-800 dark:to-gray-900 border-r border-green-200 dark:border-gray-700 p-4 h-full overflow-y-auto',
    header: 'flex items-center gap-3 mb-6 pb-4 border-b border-green-200 dark:border-gray-700',
    headerIcon: 'w-6 h-6 text-green-600 dark:text-green-400',
    headerTitle: 'text-lg font-semibold text-gray-900 dark:text-gray-100',

    // 액션 버튼
    actionSection: 'mb-6',
    addButton: 'w-full flex items-center gap-2 px-3 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg transition-colors text-sm font-medium',
    addButtonIcon: 'w-4 h-4',

    // 구조 트리
    treeContainer: 'space-y-1',
    treeItem: 'group relative',
    treeItemButton: 'w-full flex items-center gap-2 px-3 py-2 rounded-lg transition-colors text-left',
    treeItemNormal: 'hover:bg-green-100 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300',
    treeItemSelected: 'bg-green-200 dark:bg-green-900/30 text-green-800 dark:text-green-200',
    treeItemIndent: 'ml-6',

    // 아이템 아이콘 및 텍스트
    itemIcon: 'w-4 h-4 flex-shrink-0',
    itemText: 'flex-1 text-sm font-medium',
    itemMeta: 'text-xs text-gray-500 dark:text-gray-400',

    // 확장/축소 버튼
    expandButton: 'w-4 h-4 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300',

    // 메뉴 버튼
    menuButton: 'w-6 h-6 p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 rounded opacity-0 group-hover:opacity-100 transition-opacity',

    // 드롭다운 메뉴
    menu: 'absolute right-0 top-8 w-32 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-lg z-10',
    menuItem: 'flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 first:rounded-t-lg last:rounded-b-lg'
} as const;

// 아이템 타입별 아이콘
const getItemIcon = (type: StructureItem['type']) => {
    switch (type) {
        case 'synopsis': return BookOpen;
        case 'chapter': return FileText;
        case 'note': return Edit3;
        case 'folder': return FolderOpen;
        default: return FileText;
    }
};

// 아이템 타입별 색상
const getItemColor = (type: StructureItem['type']) => {
    switch (type) {
        case 'synopsis': return 'text-purple-500';
        case 'chapter': return 'text-blue-500';
        case 'note': return 'text-yellow-500';
        case 'folder': return 'text-green-500';
        default: return 'text-gray-500';
    }
};

export const StructureSidebar = memo(function StructureSidebar({
    projectId,
    structure,
    onAddItem,
    onEditItem,
    onDeleteItem,
    onSelectItem,
    selectedItemId
}: StructureSidebarProps): React.ReactElement {
    const [expandedItems, setExpandedItems] = useState<Set<string>>(new Set());
    const [openMenuId, setOpenMenuId] = useState<string | null>(null);

    Logger.debug('STRUCTURE_SIDEBAR', 'Rendering structure sidebar', {
        projectId,
        structureCount: structure.length
    });

    // 아이템 확장/축소 토글
    const toggleExpanded = (itemId: string) => {
        const newExpanded = new Set(expandedItems);
        if (newExpanded.has(itemId)) {
            newExpanded.delete(itemId);
        } else {
            newExpanded.add(itemId);
        }
        setExpandedItems(newExpanded);
    };

    // 메뉴 토글
    const toggleMenu = (itemId: string, event: React.MouseEvent) => {
        event.stopPropagation();
        setOpenMenuId(openMenuId === itemId ? null : itemId);
    };

    // 재귀적으로 구조 아이템 렌더링
    const renderStructureItem = (item: StructureItem, level: number = 0): React.ReactElement => {
        const Icon = getItemIcon(item.type);
        const iconColor = getItemColor(item.type);
        const isSelected = selectedItemId === item.id;
        const isExpanded = expandedItems.has(item.id);
        const hasChildren = item.children && item.children.length > 0;

        return (
            <div key={item.id} className={STRUCTURE_SIDEBAR_STYLES.treeItem}>
                <div
                    className={`${STRUCTURE_SIDEBAR_STYLES.treeItemButton} ${isSelected
                            ? STRUCTURE_SIDEBAR_STYLES.treeItemSelected
                            : STRUCTURE_SIDEBAR_STYLES.treeItemNormal
                        }`}
                    style={{ paddingLeft: `${12 + level * 20}px` }}
                    onClick={() => onSelectItem?.(item.id)}
                >
                    {/* 확장/축소 버튼 */}
                    {hasChildren && (
                        <button
                            onClick={(e) => {
                                e.stopPropagation();
                                toggleExpanded(item.id);
                            }}
                            className={STRUCTURE_SIDEBAR_STYLES.expandButton}
                        >
                            {isExpanded ? <ChevronDown /> : <ChevronRight />}
                        </button>
                    )}

                    {/* 아이템 아이콘 */}
                    <Icon className={`${STRUCTURE_SIDEBAR_STYLES.itemIcon} ${iconColor}`} />

                    {/* 아이템 텍스트 */}
                    <div className={STRUCTURE_SIDEBAR_STYLES.itemText}>
                        <div>{item.title}</div>
                        {item.wordCount && (
                            <div className={STRUCTURE_SIDEBAR_STYLES.itemMeta}>
                                {item.wordCount.toLocaleString()}자
                            </div>
                        )}
                    </div>

                    {/* 메뉴 버튼 */}
                    <button
                        onClick={(e) => toggleMenu(item.id, e)}
                        className={STRUCTURE_SIDEBAR_STYLES.menuButton}
                    >
                        <MoreVertical />
                    </button>
                </div>

                {/* 드롭다운 메뉴 */}
                {openMenuId === item.id && (
                    <div className={STRUCTURE_SIDEBAR_STYLES.menu}>
                        <button
                            className={STRUCTURE_SIDEBAR_STYLES.menuItem}
                            onClick={() => {
                                onEditItem?.(item.id);
                                setOpenMenuId(null);
                            }}
                        >
                            <Edit3 className="w-4 h-4" />
                            편집
                        </button>
                        <button
                            className={STRUCTURE_SIDEBAR_STYLES.menuItem}
                            onClick={() => {
                                onDeleteItem?.(item.id);
                                setOpenMenuId(null);
                            }}
                        >
                            <Trash2 className="w-4 h-4 text-red-500" />
                            삭제
                        </button>
                    </div>
                )}

                {/* 하위 아이템들 */}
                {hasChildren && isExpanded && (
                    <div>
                        {item.children!.map(child => renderStructureItem(child, level + 1))}
                    </div>
                )}
            </div>
        );
    };

    return (
        <div className={STRUCTURE_SIDEBAR_STYLES.container}>
            {/* 헤더 */}
            <div className={STRUCTURE_SIDEBAR_STYLES.header}>
                <BookOpen className={STRUCTURE_SIDEBAR_STYLES.headerIcon} />
                <h3 className={STRUCTURE_SIDEBAR_STYLES.headerTitle}>프로젝트 구조</h3>
            </div>

            {/* 추가 버튼 */}
            <div className={STRUCTURE_SIDEBAR_STYLES.actionSection}>
                <button
                    onClick={() => onAddItem?.('chapter')}
                    className={STRUCTURE_SIDEBAR_STYLES.addButton}
                >
                    <Plus className={STRUCTURE_SIDEBAR_STYLES.addButtonIcon} />
                    새 챕터 추가
                </button>
            </div>

            {/* 구조 트리 */}
            <div className={STRUCTURE_SIDEBAR_STYLES.treeContainer}>
                {structure.length === 0 ? (
                    <div className="text-center py-8 text-gray-500 dark:text-gray-400">
                        <BookOpen className="w-12 h-12 mx-auto mb-3 opacity-50" />
                        <p className="text-sm">아직 구조가 없습니다</p>
                        <p className="text-xs mt-1">새 챕터를 추가해보세요</p>
                    </div>
                ) : (
                    structure.map(item => renderStructureItem(item))
                )}
            </div>
        </div>
    );
});
