'use client';

import React, { memo } from 'react';
import {
    Edit3,
    Target,
    Clock,
    TrendingUp,
    Zap,
    FileText,
    BarChart3
} from 'lucide-react';
import { Logger } from '../../../../../../shared/logger';

interface WritingSidebarProps {
    projectId: string;
    stats: {
        wordCount: number;
        characterCount: number;
        paragraphCount: number;
        pageCount: number;
        readingTime: string;
        typingSpeed: number;
        sessionWords: number;
        dailyGoal: number;
        progressPercentage: number;
    };
    onSetGoal?: (goal: number) => void;
}

// 🔥 작가 전용 사이드바 스타일
const WRITING_SIDEBAR_STYLES = {
    container: 'w-64 bg-gradient-to-b from-blue-50 to-indigo-50 dark:from-gray-800 dark:to-gray-900 border-r border-blue-200 dark:border-gray-700 p-4 h-full overflow-y-auto',
    header: 'flex items-center gap-3 mb-6 pb-4 border-b border-blue-200 dark:border-gray-700',
    headerIcon: 'w-6 h-6 text-blue-600 dark:text-blue-400',
    headerTitle: 'text-lg font-semibold text-gray-900 dark:text-gray-100',

    // 통계 섹션
    statsGrid: 'grid grid-cols-1 gap-4 mb-6',
    statCard: 'bg-white dark:bg-gray-800 rounded-lg p-4 shadow-sm border border-blue-100 dark:border-gray-700',
    statHeader: 'flex items-center gap-2 mb-2',
    statIcon: 'w-4 h-4 text-blue-500 dark:text-blue-400',
    statLabel: 'text-sm font-medium text-gray-600 dark:text-gray-400',
    statValue: 'text-2xl font-bold text-gray-900 dark:text-gray-100',
    statSubValue: 'text-xs text-gray-500 dark:text-gray-500 mt-1',

    // 목표 설정
    goalSection: 'bg-white dark:bg-gray-800 rounded-lg p-4 shadow-sm border border-blue-100 dark:border-gray-700 mb-6',
    goalHeader: 'flex items-center gap-2 mb-3',
    goalProgress: 'w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2 mb-2',
    goalProgressBar: 'h-2 rounded-full transition-all duration-300',
    goalText: 'text-sm text-gray-600 dark:text-gray-400',

    // 세션 정보
    sessionSection: 'bg-white dark:bg-gray-800 rounded-lg p-4 shadow-sm border border-blue-100 dark:border-gray-700',
    sessionItem: 'flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700 last:border-b-0',
    sessionLabel: 'text-sm text-gray-600 dark:text-gray-400',
    sessionValue: 'text-sm font-medium text-gray-900 dark:text-gray-100'
} as const;

export const WritingSidebar = memo(function WritingSidebar({
    projectId,
    stats,
    onSetGoal
}: WritingSidebarProps): React.ReactElement {
    Logger.debug('WRITING_SIDEBAR', 'Rendering writing sidebar', { projectId, stats });

    // 진행률 계산
    const progressPercentage = Math.min((stats.wordCount / stats.dailyGoal) * 100, 100);
    const progressColor = progressPercentage >= 100 ? 'bg-green-500' :
        progressPercentage >= 70 ? 'bg-blue-500' :
            progressPercentage >= 30 ? 'bg-yellow-500' : 'bg-gray-400';

    return (
        <div className={WRITING_SIDEBAR_STYLES.container}>
            {/* 헤더 */}
            <div className={WRITING_SIDEBAR_STYLES.header}>
                <Edit3 className={WRITING_SIDEBAR_STYLES.headerIcon} />
                <h3 className={WRITING_SIDEBAR_STYLES.headerTitle}>글쓰기 통계</h3>
            </div>

            {/* 주요 통계 */}
            <div className={WRITING_SIDEBAR_STYLES.statsGrid}>
                {/* 단어 수 */}
                <div className={WRITING_SIDEBAR_STYLES.statCard}>
                    <div className={WRITING_SIDEBAR_STYLES.statHeader}>
                        <FileText className={WRITING_SIDEBAR_STYLES.statIcon} />
                        <span className={WRITING_SIDEBAR_STYLES.statLabel}>총 단어</span>
                    </div>
                    <div className={WRITING_SIDEBAR_STYLES.statValue}>
                        {stats.wordCount.toLocaleString()}
                    </div>
                    <div className={WRITING_SIDEBAR_STYLES.statSubValue}>
                        {stats.characterCount.toLocaleString()} 글자
                    </div>
                </div>

                {/* 타이핑 속도 */}
                <div className={WRITING_SIDEBAR_STYLES.statCard}>
                    <div className={WRITING_SIDEBAR_STYLES.statHeader}>
                        <Zap className={WRITING_SIDEBAR_STYLES.statIcon} />
                        <span className={WRITING_SIDEBAR_STYLES.statLabel}>타이핑 속도</span>
                    </div>
                    <div className={WRITING_SIDEBAR_STYLES.statValue}>
                        {stats.typingSpeed}
                    </div>
                    <div className={WRITING_SIDEBAR_STYLES.statSubValue}>
                        단어/분
                    </div>
                </div>

                {/* 읽기 시간 */}
                <div className={WRITING_SIDEBAR_STYLES.statCard}>
                    <div className={WRITING_SIDEBAR_STYLES.statHeader}>
                        <Clock className={WRITING_SIDEBAR_STYLES.statIcon} />
                        <span className={WRITING_SIDEBAR_STYLES.statLabel}>읽기 시간</span>
                    </div>
                    <div className={WRITING_SIDEBAR_STYLES.statValue}>
                        {stats.readingTime}
                    </div>
                    <div className={WRITING_SIDEBAR_STYLES.statSubValue}>
                        {stats.pageCount} 페이지
                    </div>
                </div>
            </div>

            {/* 일일 목표 */}
            <div className={WRITING_SIDEBAR_STYLES.goalSection}>
                <div className={WRITING_SIDEBAR_STYLES.goalHeader}>
                    <Target className={WRITING_SIDEBAR_STYLES.statIcon} />
                    <span className={WRITING_SIDEBAR_STYLES.statLabel}>일일 목표</span>
                </div>

                <div className={WRITING_SIDEBAR_STYLES.goalProgress}>
                    <div
                        className={`${WRITING_SIDEBAR_STYLES.goalProgressBar} ${progressColor}`}
                        style={{ width: `${progressPercentage}%` }}
                    />
                </div>

                <div className={WRITING_SIDEBAR_STYLES.goalText}>
                    {stats.wordCount} / {stats.dailyGoal.toLocaleString()} 단어 ({progressPercentage.toFixed(0)}%)
                </div>

                {progressPercentage >= 100 && (
                    <div className="text-green-600 dark:text-green-400 text-sm font-medium mt-2">
                        🎉 오늘 목표 달성!
                    </div>
                )}
            </div>

            {/* 세션 정보 */}
            <div className={WRITING_SIDEBAR_STYLES.sessionSection}>
                <div className={WRITING_SIDEBAR_STYLES.goalHeader}>
                    <TrendingUp className={WRITING_SIDEBAR_STYLES.statIcon} />
                    <span className={WRITING_SIDEBAR_STYLES.statLabel}>오늘 세션</span>
                </div>

                <div className={WRITING_SIDEBAR_STYLES.sessionItem}>
                    <span className={WRITING_SIDEBAR_STYLES.sessionLabel}>세션 단어</span>
                    <span className={WRITING_SIDEBAR_STYLES.sessionValue}>
                        {stats.sessionWords.toLocaleString()}
                    </span>
                </div>

                <div className={WRITING_SIDEBAR_STYLES.sessionItem}>
                    <span className={WRITING_SIDEBAR_STYLES.sessionLabel}>문단 수</span>
                    <span className={WRITING_SIDEBAR_STYLES.sessionValue}>
                        {stats.paragraphCount}
                    </span>
                </div>

                <div className={WRITING_SIDEBAR_STYLES.sessionItem}>
                    <span className={WRITING_SIDEBAR_STYLES.sessionLabel}>평균 속도</span>
                    <span className={WRITING_SIDEBAR_STYLES.sessionValue}>
                        {stats.typingSpeed} WPM
                    </span>
                </div>
            </div>
        </div>
    );
});
