'use client';

import React, { memo } from 'react';
import { WritingSidebar } from './WritingSidebar';
import { StructureSidebar } from './StructureSidebar';
import { CharacterSidebar } from './CharacterSidebar';
import { NoteSidebar } from './NoteSidebar';
import { Logger } from '../../../../../../shared/logger';

interface DynamicSidebarProps {
    projectId: string;
    currentView: string;

    // 글쓰기 뷰 props
    writerStats?: {
        wordCount: number;
        characterCount: number;
        paragraphCount: number;
        pageCount: number;
        readingTime: string;
        typingSpeed: number;
        sessionWords: number;
        dailyGoal: number;
        progressPercentage: number;
    };

    // 구조 뷰 props
    structure?: Array<{
        id: string;
        title: string;
        type: 'synopsis' | 'chapter' | 'note' | 'folder';
        children?: any[];
        wordCount?: number;
        isExpanded?: boolean;
    }>;

    // 인물 뷰 props
    characters?: Array<{
        id: string;
        name: string;
        role: 'protagonist' | 'antagonist' | 'supporting' | 'minor';
        description: string;
        relationships: Array<{
            characterId: string;
            type: 'family' | 'friend' | 'enemy' | 'love' | 'ally';
            description: string;
        }>;
        notes: string;
        avatarUrl?: string;
    }>;

    // 메모 뷰 props
    notes?: Array<{
        id: string;
        title: string;
        content: string;
        tags: string[];
        category: 'research' | 'idea' | 'plot' | 'character' | 'dialogue' | 'other';
        priority: 'low' | 'medium' | 'high';
        createdAt: Date;
        updatedAt: Date;
        isPinned: boolean;
    }>;

    // 콜백 함수들
    onSetWordGoal?: (goal: number) => void;
    onAddStructureItem?: (type: 'synopsis' | 'chapter' | 'note' | 'folder', parentId?: string) => void;
    onEditStructureItem?: (id: string) => void;
    onDeleteStructureItem?: (id: string) => void;
    onSelectStructureItem?: (id: string) => void;
    onAddCharacter?: () => void;
    onEditCharacter?: (id: string) => void;
    onDeleteCharacter?: (id: string) => void;
    onSelectCharacter?: (id: string) => void;
    onAddNote?: () => void;
    onEditNote?: (id: string) => void;
    onDeleteNote?: (id: string) => void;
    onSelectNote?: (id: string) => void;
    onToggleNotePin?: (id: string) => void;

    // 선택된 아이템 ID들
    selectedStructureId?: string;
    selectedCharacterId?: string;
    selectedNoteId?: string;
}

export const DynamicSidebar = memo(function DynamicSidebar({
    projectId,
    currentView,
    writerStats,
    structure = [],
    characters = [],
    notes = [],
    onSetWordGoal,
    onAddStructureItem,
    onEditStructureItem,
    onDeleteStructureItem,
    onSelectStructureItem,
    onAddCharacter,
    onEditCharacter,
    onDeleteCharacter,
    onSelectCharacter,
    onAddNote,
    onEditNote,
    onDeleteNote,
    onSelectNote,
    onToggleNotePin,
    selectedStructureId,
    selectedCharacterId,
    selectedNoteId
}: DynamicSidebarProps): React.ReactElement {
    Logger.debug('DYNAMIC_SIDEBAR', 'Rendering dynamic sidebar', {
        projectId,
        currentView,
        hasWriterStats: !!writerStats,
        structureCount: structure.length,
        charactersCount: characters.length,
        notesCount: notes.length
    });

    // 뷰에 따른 사이드바 렌더링
    switch (currentView) {
        case 'write':
            return (
                <WritingSidebar
                    projectId={projectId}
                    stats={writerStats || {
                        wordCount: 0,
                        characterCount: 0,
                        paragraphCount: 0,
                        pageCount: 0,
                        readingTime: '0분',
                        typingSpeed: 0,
                        sessionWords: 0,
                        dailyGoal: 1000,
                        progressPercentage: 0
                    }}
                    onSetGoal={onSetWordGoal}
                />
            );

        case 'structure':
            return (
                <StructureSidebar
                    projectId={projectId}
                    structure={structure}
                    onAddItem={onAddStructureItem}
                    onEditItem={onEditStructureItem}
                    onDeleteItem={onDeleteStructureItem}
                    onSelectItem={onSelectStructureItem}
                    selectedItemId={selectedStructureId}
                />
            );

        case 'characters':
            return (
                <CharacterSidebar
                    projectId={projectId}
                    characters={characters}
                    onAddCharacter={onAddCharacter}
                    onEditCharacter={onEditCharacter}
                    onDeleteCharacter={onDeleteCharacter}
                    onSelectCharacter={onSelectCharacter}
                    selectedCharacterId={selectedCharacterId}
                />
            );

        case 'notes':
            return (
                <NoteSidebar
                    projectId={projectId}
                    notes={notes}
                    onAddNote={onAddNote}
                    onEditNote={onEditNote}
                    onDeleteNote={onDeleteNote}
                    onSelectNote={onSelectNote}
                    onTogglePin={onToggleNotePin}
                    selectedNoteId={selectedNoteId}
                />
            );

        // 기본값으로 WritingSidebar 사용
        default:
            return (
                <WritingSidebar
                    projectId={projectId}
                    stats={writerStats || {
                        wordCount: 0,
                        characterCount: 0,
                        paragraphCount: 0,
                        pageCount: 0,
                        readingTime: '0분',
                        typingSpeed: 0,
                        sessionWords: 0,
                        dailyGoal: 1000,
                        progressPercentage: 0
                    }}
                    onSetGoal={onSetWordGoal}
                />
            );
    }
});

// Export all sidebar components for individual use
export { WritingSidebar, StructureSidebar, CharacterSidebar, NoteSidebar };
