'use client';

import React, { memo, useState } from 'react';
import {
    Users,
    Plus,
    Search,
    UserPlus,
    Heart,
    Sword,
    Crown,
    Star,
    MoreHorizontal,
    Edit3,
    Trash2
} from 'lucide-react';
import { Logger } from '../../../../../../shared/logger';

interface Character {
    id: string;
    name: string;
    role: 'protagonist' | 'antagonist' | 'supporting' | 'minor';
    description: string;
    relationships: Array<{
        characterId: string;
        type: 'family' | 'friend' | 'enemy' | 'love' | 'ally';
        description: string;
    }>;
    notes: string;
    avatarUrl?: string;
}

interface CharacterSidebarProps {
    projectId: string;
    characters: Character[];
    onAddCharacter?: () => void;
    onEditCharacter?: (id: string) => void;
    onDeleteCharacter?: (id: string) => void;
    onSelectCharacter?: (id: string) => void;
    selectedCharacterId?: string;
}

// 🔥 인물 관리 전용 사이드바 스타일
const CHARACTER_SIDEBAR_STYLES = {
    container: 'w-64 bg-gradient-to-b from-purple-50 to-pink-50 dark:from-gray-800 dark:to-gray-900 border-r border-purple-200 dark:border-gray-700 p-4 h-full overflow-y-auto',
    header: 'flex items-center gap-3 mb-6 pb-4 border-b border-purple-200 dark:border-gray-700',
    headerIcon: 'w-6 h-6 text-purple-600 dark:text-purple-400',
    headerTitle: 'text-lg font-semibold text-gray-900 dark:text-gray-100',

    // 검색 및 액션
    actionSection: 'mb-6 space-y-3',
    searchBox: 'w-full px-3 py-2 border border-purple-200 dark:border-gray-600 rounded-lg text-sm bg-white dark:bg-gray-800 placeholder-gray-500',
    addButton: 'w-full flex items-center gap-2 px-3 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg transition-colors text-sm font-medium',
    addButtonIcon: 'w-4 h-4',

    // 인물 카드
    characterList: 'space-y-3',
    characterCard: 'bg-white dark:bg-gray-800 rounded-lg p-3 border border-purple-100 dark:border-gray-700 transition-all hover:shadow-md',
    characterCardSelected: 'bg-purple-100 dark:bg-purple-900/30 border-purple-300 dark:border-purple-600',
    characterHeader: 'flex items-center gap-3 mb-2',
    characterAvatar: 'w-8 h-8 rounded-full bg-purple-200 dark:bg-purple-800 flex items-center justify-center text-purple-600 dark:text-purple-400 text-sm font-semibold',
    characterInfo: 'flex-1',
    characterName: 'font-medium text-gray-900 dark:text-gray-100 text-sm',
    characterRole: 'text-xs text-gray-500 dark:text-gray-400',
    characterMenu: 'w-6 h-6 p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 rounded',

    // 인물 상세
    characterDesc: 'text-xs text-gray-600 dark:text-gray-400 line-clamp-2 mb-2',
    characterStats: 'flex items-center gap-2 text-xs text-gray-500',

    // 역할별 아이콘
    roleIcon: 'w-4 h-4',

    // 빈 상태
    emptyState: 'text-center py-8 text-gray-500 dark:text-gray-400',
    emptyIcon: 'w-12 h-12 mx-auto mb-3 opacity-50',
    emptyText: 'text-sm',
    emptySubtext: 'text-xs mt-1'
} as const;

// 역할별 아이콘 및 색상
const getRoleIcon = (role: Character['role']) => {
    switch (role) {
        case 'protagonist': return { icon: Star, color: 'text-yellow-500' };
        case 'antagonist': return { icon: Sword, color: 'text-red-500' };
        case 'supporting': return { icon: Heart, color: 'text-blue-500' };
        case 'minor': return { icon: Crown, color: 'text-gray-500' };
        default: return { icon: Users, color: 'text-gray-500' };
    }
};

// 역할별 한글 이름
const getRoleName = (role: Character['role']) => {
    switch (role) {
        case 'protagonist': return '주인공';
        case 'antagonist': return '적대자';
        case 'supporting': return '조연';
        case 'minor': return '단역';
        default: return '기타';
    }
};

export const CharacterSidebar = memo(function CharacterSidebar({
    projectId,
    characters,
    onAddCharacter,
    onEditCharacter,
    onDeleteCharacter,
    onSelectCharacter,
    selectedCharacterId
}: CharacterSidebarProps): React.ReactElement {
    const [searchTerm, setSearchTerm] = useState('');
    const [openMenuId, setOpenMenuId] = useState<string | null>(null);

    Logger.debug('CHARACTER_SIDEBAR', 'Rendering character sidebar', {
        projectId,
        characterCount: characters.length
    });

    // 검색 필터링
    const filteredCharacters = characters.filter(character =>
        character.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        character.description.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // 메뉴 토글
    const toggleMenu = (characterId: string, event: React.MouseEvent) => {
        event.stopPropagation();
        setOpenMenuId(openMenuId === characterId ? null : characterId);
    };

    return (
        <div className={CHARACTER_SIDEBAR_STYLES.container}>
            {/* 헤더 */}
            <div className={CHARACTER_SIDEBAR_STYLES.header}>
                <Users className={CHARACTER_SIDEBAR_STYLES.headerIcon} />
                <h3 className={CHARACTER_SIDEBAR_STYLES.headerTitle}>인물 관리</h3>
            </div>

            {/* 검색 및 추가 버튼 */}
            <div className={CHARACTER_SIDEBAR_STYLES.actionSection}>
                <div className="relative">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                        type="text"
                        placeholder="인물 검색..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className={`${CHARACTER_SIDEBAR_STYLES.searchBox} pl-10`}
                    />
                </div>

                <button
                    onClick={onAddCharacter}
                    className={CHARACTER_SIDEBAR_STYLES.addButton}
                >
                    <UserPlus className={CHARACTER_SIDEBAR_STYLES.addButtonIcon} />
                    새 인물 추가
                </button>
            </div>

            {/* 인물 목록 */}
            <div className={CHARACTER_SIDEBAR_STYLES.characterList}>
                {filteredCharacters.length === 0 ? (
                    <div className={CHARACTER_SIDEBAR_STYLES.emptyState}>
                        <Users className={CHARACTER_SIDEBAR_STYLES.emptyIcon} />
                        <p className={CHARACTER_SIDEBAR_STYLES.emptyText}>
                            {searchTerm ? '검색 결과가 없습니다' : '아직 인물이 없습니다'}
                        </p>
                        <p className={CHARACTER_SIDEBAR_STYLES.emptySubtext}>
                            {searchTerm ? '다른 검색어를 시도해보세요' : '새 인물을 추가해보세요'}
                        </p>
                    </div>
                ) : (
                    filteredCharacters.map(character => {
                        const { icon: RoleIcon, color } = getRoleIcon(character.role);
                        const isSelected = selectedCharacterId === character.id;

                        return (
                            <div
                                key={character.id}
                                className={`${CHARACTER_SIDEBAR_STYLES.characterCard} ${isSelected ? CHARACTER_SIDEBAR_STYLES.characterCardSelected : ''
                                    } group cursor-pointer`}
                                onClick={() => onSelectCharacter?.(character.id)}
                            >
                                {/* 헤더 */}
                                <div className={CHARACTER_SIDEBAR_STYLES.characterHeader}>
                                    <div className={CHARACTER_SIDEBAR_STYLES.characterAvatar}>
                                        {character.name.charAt(0)}
                                    </div>

                                    <div className={CHARACTER_SIDEBAR_STYLES.characterInfo}>
                                        <div className={CHARACTER_SIDEBAR_STYLES.characterName}>
                                            {character.name}
                                        </div>
                                        <div className={CHARACTER_SIDEBAR_STYLES.characterRole}>
                                            <RoleIcon className={`inline w-3 h-3 mr-1 ${color}`} />
                                            {getRoleName(character.role)}
                                        </div>
                                    </div>

                                    <button
                                        onClick={(e) => toggleMenu(character.id, e)}
                                        className={`${CHARACTER_SIDEBAR_STYLES.characterMenu} opacity-0 group-hover:opacity-100 transition-opacity`}
                                    >
                                        <MoreHorizontal />
                                    </button>
                                </div>

                                {/* 설명 */}
                                {character.description && (
                                    <div className={CHARACTER_SIDEBAR_STYLES.characterDesc}>
                                        {character.description}
                                    </div>
                                )}

                                {/* 통계 */}
                                <div className={CHARACTER_SIDEBAR_STYLES.characterStats}>
                                    <span>관계 {character.relationships.length}개</span>
                                    {character.notes && <span>• 노트 있음</span>}
                                </div>

                                {/* 드롭다운 메뉴 */}
                                {openMenuId === character.id && (
                                    <div className="absolute right-2 top-8 w-28 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-lg z-10">
                                        <button
                                            className="flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 w-full text-left rounded-t-lg"
                                            onClick={() => {
                                                onEditCharacter?.(character.id);
                                                setOpenMenuId(null);
                                            }}
                                        >
                                            <Edit3 className="w-4 h-4" />
                                            편집
                                        </button>
                                        <button
                                            className="flex items-center gap-2 px-3 py-2 text-sm text-red-600 hover:bg-gray-100 dark:hover:bg-gray-700 w-full text-left rounded-b-lg"
                                            onClick={() => {
                                                onDeleteCharacter?.(character.id);
                                                setOpenMenuId(null);
                                            }}
                                        >
                                            <Trash2 className="w-4 h-4" />
                                            삭제
                                        </button>
                                    </div>
                                )}
                            </div>
                        );
                    })
                )}
            </div>
        </div>
    );
});
